pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 n) public {
        // Keep n in a feasible range to avoid unlimited loop, but large enough to trigger overflow
        vm.assume(n < 500);
        // Repeatedly deposit 0 wei up to n times
        for (uint256 i = 0; i < n; i++) {
            (bool ok, ) = address(c).call{value: 0}("");
            require(ok, "deposit failed");
        }
        // After any number of deposits, depositsCount must be strictly greater than 0
        assertTrue(c.depositsCount() > 0);
    }
}

