pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, uint256 callCount) public {
        // Bound the call count to a reasonable range to avoid infinite loop
        uint256 times = bound(callCount, 1, 20);
        // Bound the amount to a reasonable range and avoid overflow
        amount = bound(amount, 1 ether, 100 ether);

        // Fund the caller with enough ether for all calls
        address caller = address(0x1234);
        vm.deal(caller, amount * times + 1 ether);

        uint256 expectedCount = 0;

        vm.startPrank(caller);
        for (uint256 i = 0; i < times; i++) {
            // Send ether to c via receive()
            (bool success, ) = address(c).call{value: amount}("");
            // The reference C always accepts the deposit (since depositsCount+1 >= depositsCount is always true for reasonable counts)
            // Assume the call succeeds; if it reverts, we skip counting.
            if (success) {
                expectedCount++;
            }
        }
        vm.stopPrank();

        // The invariant: depositsCount must equal the number of successful deposits.
        assertEq(c.depositsCount(), expectedCount, "depositsCount must equal number of successful deposits");
    }
}

