pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount) public {
        // Bound deposit to a reasonable range to avoid overflow revert on receive
        depositAmount = bound(depositAmount, 1, type(uint256).max - 1);
        // Setup: msg.sender is the owner (deploys c). Fund owner.
        address owner = c.owner();
        vm.deal(owner, depositAmount);

        // Deposit Ether into the contract
        vm.prank(owner);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        // Record owner's balance before withdrawal
        uint256 balanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Owner calls withdrawAll
        vm.prank(owner);
        c.withdrawAll();

        // Owner's balance after withdrawal
        uint256 balanceAfter = owner.balance;

        // General rule: owner's balance increase exactly equals the contract's balance before the call.
        // The correct contract transfers full balance, the buggy one transfers 0.
        assertTrue(balanceAfter - balanceBefore == contractBalanceBefore);
    }
}

