pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposit, uint256 extraDeposits, uint256 seed) public {
        // Bound initial deposit to a reasonable range to avoid overflow in depositsCount
        initialDeposit = bound(initialDeposit, 1, 1 ether);
        // Ensure enough ETH for the owner to send
        address owner = c.owner();
        vm.deal(owner, 100 ether);
        // Owner sends initial deposit
        vm.prank(owner);
        (bool ok,) = address(c).call{value: initialDeposit}("");
        require(ok, "initial deposit failed");
        // Fuzz extra deposits made by the owner
        extraDeposits = bound(extraDeposits, 0, 10);
        for (uint i = 0; i < extraDeposits; i++) {
            uint amount = bound(uint(keccak256(abi.encode(seed, i))), 1, 1 ether);
            vm.deal(owner, owner.balance + amount);
            vm.prank(owner);
            (bool s,) = address(c).call{value: amount}("");
            require(s, "extra deposit failed");
        }
        // Record balances before withdrawAll
        uint ownerBalanceBefore = owner.balance;
        uint contractBalanceBefore = address(c).balance;
        // Owner calls withdrawAll
        vm.prank(owner);
        c.withdrawAll();
        // Assert: owner balance increased by exactly the contract's prior balance
        assertEq(owner.balance, ownerBalanceBefore + contractBalanceBefore);
    }
}

