import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, bytes memory data) public {
        // 1. Bound amount to avoid arithmetic overflow in receive
        amount = bound(amount, 1, type(uint256).max - 1);

        // 2. Fund the contract via receive to have a balance to withdraw
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "fund failed");

        // 3. Set owner to this test contract and call sendMoney
        // Owner is this test contract because it deployed c
        vm.prank(address(this));
        c.sendMoney(address(0), 0, data);

        // 4. Attempt to withdraw all and check if it succeeds
        bool ok;
        vm.prank(address(this));
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // 5. Assert: withdrawal must not revert
        assertTrue(ok);
    }
}

